def count_pairs(xs, k):
    """
    Returns the number of index pairs (i, j) such that i < j and xs[i] + xs[j] == k.

    Constraints:
    - For empty input ([]) return 0.
    - Raise TypeError if the first argument is not a list.
    - The function must not use sorted, sort, or itertools.
    - At most one loop statement is allowed.
    """
    if not isinstance(xs, list):
        raise TypeError("The first argument must be a list.")
    if not xs:
        return 0

    count = 0
    seen = {}
    for j in range(len(xs)):
        complement = k - xs[j]
        if complement in seen:
            count += seen[complement]
        if xs[j] in seen:
            seen[xs[j]] += 1
        else:
            seen[xs[j]] = 1
    return count
